            break;
        case MODO_MANUAL:
            manejar_modo_manual(msg);
            break;
        case DATOS_VARIABLES:
            manejar_datos_variables(msg);
            break;
        case GRAFICAS:
            manejar_graficas(msg);
            break;
        case CINEMATICAINVERSA:
            manejar_cinematica_inversa(msg);
            break;
