// ----------------------- TAREA DE CONTROL -----------------------
void ControlTask(void *pvParameters) {
    const TickType_t xDelay = pdMS_TO_TICKS(10);
    const bool Observador = false;

    // ====================== FORMAS =======================
    int N_actual = 1;
    int idx = 0;
    
    //Parámetros del touch
    float Xlargo = 176.0f; // mm
    float Ylargo = 131.0f; // mm
    float Xmin = 97, Xmax = 910;
    float Ymin = 172, Ymax = 867;

    float setpointX = 530.0f;
    float setpointY = 490.0f;
    //float setpointX = (Xmax-Xmin)/2;
    //float setpointY = (Ymax-Ymin)/2;

    // ======================= CONTROL PID =======================

    float pid_output_min = -330;  // Mínimo valor esperado del PID
    float pid_output_max =  330;   // Máximo valor esperado del PID

    float output_min = -0.2;          // Mínimo valor después del mapeo
    float output_max =  0.2;        // Máximo valor después del mapeo

    float errorX = 0, errorY = 0;
    float outputX = 0, outputY = 0;


    //======================= CINEMATICA INVERSA =======================
    String inputString;
    // Datos deseados
    double hz = 3.0;
    double nx = 0.0;
    double ny = 0.0;
    datosIK.nx = nx;
    datosIK.ny = ny;
    datosIK.hz = hz;

    // ============================ SEGUIDOR =================================
    // --- Parámetros del controlador ---
    const float conversorX = (Xlargo/1000) / (Xmax-Xmin);               // metros por unidad sensor X
    const float conversorY = (Ylargo/1000) / (Ymax-Ymin);               // metros por unidad sensor Y
    const float Ts = 0.01f;      // 10 ms 
    
    // float Kp_d[4] = { 0.499955801150480, 0.809929703696406, 5.528608463592072, 3.308380765901717 };
    // float Ki_d = -0.142763742825935; //Funcional 1

    // float Kp_d[4] = { 0.371724983341552, 0.649266229758272, 4.786020118245523, 3.088125056519716 };
    // float Ki_d = -0.098946999257402; //Funcional No agresivo

    // float Kp_d[4] = { 0.671724983341552, 0.549266229758272, 4.786020118245523, 3.088125056519716 };
    // float Ki_d = -0.98946999257402; //Circulo


    float Kp_d[4] = { 0.71724983341552, 0.449266229758272, 4.786020118245523, 3.088125056519716 };
    float Ki_d = -0.60946999257402; //Circulo
    float xseg[4] = {0,0,0,0};
    float yseg[4] = {0,0,0,0};
    
    bool xhat_initialized = false;

    // --- Estados ---

    float zX = 0.0f;              // integrador
    float zY = 0.0f;              // integrador
    float prevMeasuredX = 0.0f;
    float prevMeasuredY = 0.0f;
    float uX = 0.0f;
    float uY = 0.0f;

    // --- Límite de saturación ---
    const float u_min = -0.35f;
    const float u_max = 0.35f; //original 0.35

    //======================= RED NEURONAL =======================

    inicializar_red();

    float angleIn = 0.0f;
    float radioX = 0.0f;
    float radioY = 0.0f;
    float radioXmag = 0.0f;
    float radioYmag = 0.0f;
    float vx = 0.0f;
    float vy = 0.0f;
    float Rvecx[6] = {};
    float Rvecy[6] = {};
    float R4x = 0.0f;
    float R5x = 0.0f;
    float R4y = 0.0f;
    float R5y = 0.0f;                        
    float R6x = 0.0f;
    float R7x = 0.0f;


    while (true) {
        switch (pantalla_actual) {
            
            case FORMAS:
            case GRAFICAS:
            case METODO_CONTROL: {
                
                if(!MotorInit){
                    datosParaEnviar.KpMotor = 50;

                    datosParaEnviar.anguloX = 57;
                    datosParaEnviar.anguloY = 57;
                    datosParaEnviar.anguloZ = 57;
                    MotorInit = true;
                    vTaskDelay(2000);
                    datosParaEnviar.KpMotor = 800;
                }
                
                //ESP_LOGI(TAG, "KPMOTOR: %d", datosParaEnviar.KpMotor);

                uint16_t measuredX = datos_display.touchX;
                uint16_t measuredY = datos_display.touchY;


                //ESP_LOGI(TAG, "measuredX %d, measuredY %d", measuredX, measuredY);

                //Si el menu de formas tiene una opción seleccionada diferente a "Ninguno", el método de control obligatoriamente será PID
                if(forma_control_sw != 0){
                    metodo_control_sw = 2;

                    float values[4] ={ 0.71724983341552, 0.449266229758272, 4.786020118245523, 3.088125056519716 }; 
                    for(int i = 0; i < 5; i++) Kp_d[i] = values[i];
                    Ki_d = -0.60946999257402; //Circulo
                }
                else{
                    float values[4] =  { 0.671724983341552, 0.549266229758272, 4.786020118245523, 3.088125056519716 };
                    for(int i = 0; i < 5; i++) Kp_d[i] = values[i];
                    Ki_d = -0.98946999257402; //Circulo
                }


                // Serial.print(measuredX * conversorX, 6);  // 6 decimales
                // Serial.print(",");
                // Serial.println(measuredY * conversorY, 6);

                
                switch(metodo_control_sw){

                    // ==================================Sin control=================================
                    case 0:{
                        
                       
                        errorX = 0;
                        errorY = 0;
                        outputX = 0;
                        outputY = 0;
                        idx = 0;

                        InverseKinematics(3.2, 0.0, 0.0);

                                        // Si hay datos disponibles en el puerto serie
                        if (Serial.available()) {
                            inputString = Serial.readStringUntil('\n');  // lee hasta salto de línea
                            inputString.trim();                          // quita espacios

                            // Array para guardar hasta 6 partes
                            String parts[6];
                            int lastIndex = 0;
                            int partIndex = 0;

                            // Divide por comas
                            for (int i = 0; i < inputString.length(); i++) {
                                if (inputString.charAt(i) == ',' || i == inputString.length() - 1) {
                                    int end = (i == inputString.length() - 1) ? i + 1 : i;
                                    parts[partIndex++] = inputString.substring(lastIndex, end);
                                    lastIndex = i + 1;
                                    if (partIndex >= 6) break; // no más de 6
                                }
                            }

                            if (partIndex == 6) {
                                Kpx = parts[0].toDouble();
                                Kix = parts[1].toDouble();
                                Kdx = parts[2].toDouble();
                                Kpy = parts[3].toDouble();
                                Kiy = parts[4].toDouble();
                                Kdy = parts[5].toDouble();

                                Serial.printf("Recibido X: Kp=%.3f Ki=%.3f Kd=%.3f | Y: Kp=%.3f Ki=%.3f Kd=%.3f\n",
                                            Kpx, Kix, Kdx, Kpy, Kiy, Kdy);
                            } else {
                                Serial.println("Error: formato inválido, usa Kpx,Kix,Kdx,Kpy,Kiy,Kdy");
                            }
                        }
                    
                        break;
                    }
                    
                    // ========================================= P I D ===========================================
                    case 1: {

                        switch(forma_control_sw){
                            //Elipse
                            case 1:
                                setpointX = setpointX_array_elipse[idx];
                                setpointY = setpointY_array_elipse[idx];
                                N_actual = N_POINTS_ELIPSE;
                                break;
                            //Cuadrado
                            case 2:
                                setpointX = setpointX_array2[idx];
                                setpointY = setpointY_array2[idx];
                                N_actual = N_POINTS_CUADRADO;
                                break;
                            //Infinito
                            case 3:
                                setpointX = setpoint_infX[idx];
                                setpointY = setpoint_infY[idx];
                                N_actual = N_POINTS_INFINITO;
                                break;

                            default:        
                                setpointX = 530.0f;
                                setpointY = 490.0f;
                                break;
                        }


                        PID(setpointX, measuredX, Ts, Kpx, Kdx, Kix, outputX, errorX, pidX); // dt = 50 ms = 0.05 s
                        outputX = map_output(outputX,pid_output_min,pid_output_max,output_min,output_max);


                        //modificar el max and min
                        PID(setpointY, measuredY, Ts, Kpy, Kdy, Kiy, outputY, errorY, pidY);
                        outputY = map_output(outputY,pid_output_min,pid_output_max,-0.35,0.35);

                        InverseKinematics(3.2, outputX, outputY);


                        idx = (idx + 1) % N_actual;


                        #if DEBUG_CONTROL
                        //ESP_LOGI(TAG, "outputX %f\n", outputX);
                        //ESP_LOGI(TAG, "outputY %f\n", outputY);
                        ESP_LOGI(TAG, "errorX %f", errorX);
                        ESP_LOGI(TAG, "errorY %f", errorY);
                        #endif

                        break;
                    }
      
                    //======================================= S E G U I D O R ========================================
                    case 2:{   
                        
                        // ==================================== OBSERVADOR =======================================
                        if (Observador){
                            float y_measX = (float)measuredX*conversorX;
                            float y_measY = (float)measuredY*conversorY;
                            float refX = setpointX * conversorX;
                            float refY = setpointY * conversorY;
                            
                            if (!xhat_initialized) {
                                x_hatX[0] = y_measX;   // posición inicial
                                x_hatY[0] = y_measY;
                                xhat_initialized = true;
                            }

                            float x_predX[4] = {0}, x_predY[4] = {0};

                            // Predicción
                            for (int i = 0; i < 4; i++) {
                                for (int j = 0; j < 4; j++) {
                                    x_predX[i] += Ad[i][j] * x_hatX[j];
                                    x_predY[i] += Ad[i][j] * x_hatY[j];
                                }
                                x_predX[i] += Bd[i] * (-uX);
                                x_predY[i] += Bd[i] * (-uY);
                            }

                            // Corrección con la medición
                            float y_hatX = x_hatX[0];
                            float y_hatY = x_hatY[0];
                            float innovX = y_measX - y_hatX;
                            float innovY = y_measY - y_hatY;
                            
                            for (int i = 0; i < 4; i++) {
                                x_hatX[i] = x_predX[i] + LdX[i] * innovX;
                                x_hatY[i] = x_predY[i] + LdY[i] * innovY;
                            }
                            
                            // ----- CONTROLADOR LQI -----
                            float u_ctrlX = 0.0, u_ctrlY = 0.0;
                            for (int i = 0; i < 4; i++) {
                                u_ctrlX -= Kp_dX[i] * x_hatX[i];
                                u_ctrlY -= Kp_dY[i] * x_hatY[i];
                            }
                            u_ctrlX += Ki_dX * integX;
                            u_ctrlY += Ki_dY * integY;
                            ESP_LOGI(TAG, "xhatX: %.6g %.6g %.6g %.6g", x_hatX[0], x_hatX[1], x_hatX[2], x_hatX[3]);
                            ESP_LOGI(TAG,"uX: %f Uy: %f", u_ctrlX, u_ctrlY);
                            
                            // ----- INTEGRADOR -----
                            float u_satX = constrain(u_ctrlX, -0.1, 0.1);
                            float u_satY = constrain(u_ctrlY, -0.1, 0.1);

                            // // anti-windup:
                            if (fabs(u_ctrlX - u_satX) < 1e-4)
                                integX += (refX - y_measX) * Ts;

                            if (fabs(u_ctrlY - u_satY) < 1e-4)
                                integY += (refY - y_measY) * Ts;


                            // ----- SATURACION Y SALIDA -----
                            uX = u_satX;
                            uY = u_satY;

                            // Aplica a la cinemática inversa
                            InverseKinematics(3.2, -uX, -uY);
                        }

                        //================================= NO OBSERVADOR ===============================

                        else{

                            switch(forma_control_sw){
                                //Elipse
                                case 1:
                                    setpointX = setpointX_array_elipse[idx];
                                    setpointY = setpointY_array_elipse[idx];
                                    N_actual = N_POINTS_ELIPSE;
                                    break;
                                //Cuadrado
                                case 2:
                                    setpointX = setpointX_array2[idx];
                                    setpointY = setpointY_array2[idx];
                                    N_actual = N_POINTS_CUADRADO;
                                    break;
                                //Infinito
                                case 3:
                                    setpointX = setpoint_infX[idx];
                                    setpointY = setpoint_infY[idx];
                                    N_actual = N_POINTS_INFINITO;
                                    break;

                                default:        
                                    setpointX = 530.0f;
                                    setpointY = 490.0f;
                                    break;
                            }

            


                            float Xy = measuredX * conversorX;
                            float Yy = measuredY * conversorY;
                            float x_ref = setpointX * conversorX;
                            float y_ref = setpointY * conversorY;

                            const float alpha = 0.2f;

                            xseg[0] = Xy;  
                            yseg[0] = Yy;
    


                            float derivadaX = (Xy - prevMeasuredX) / Ts;
                            xseg[1] = alpha * derivadaX + (1 - alpha) * xseg[1];  // suaviza
                            prevMeasuredX = Xy;

                            float derivadaY = (Yy - prevMeasuredY) / Ts;
                            yseg[1] = alpha * derivadaY + (1 - alpha) * yseg[1];
                            prevMeasuredY = Yy;

                            

                            // 2. Calcular control discreto
                            float u_unsatX = 0.0f;
                            for (int i = 0; i < 4; i++) {
                                u_unsatX += Kp_d[i] * xseg[i];
                            }
                            u_unsatX += Ki_d * zX;

                            float u_unsatY = 0.0f;
                            for (int i = 0; i < 4; i++) {
                                u_unsatY += Kp_d[i] * yseg[i];
                            }
                            u_unsatY += Ki_d * zY;


                            // 3. Saturación
                            if (u_unsatX > u_max) uX = u_max; 
                            else if (u_unsatX < u_min) uX = u_min; 
                            else uX = u_unsatX; 
                            
                            if (u_unsatY > u_max) uY = u_max; 
                            else if (u_unsatY < u_min) uY = u_min; 
                            else uY = u_unsatY;

                            if (u_unsatX < u_max && u_unsatX > u_min) {
                                zX += Ts * errorX;
                            }
                            if (u_unsatY < u_max && u_unsatY > u_min) {
                                zY += Ts * errorY;
                            }

                            // 4. Actualizar integrador
                            zX += Ts * (x_ref - Xy);
                            zY += Ts * (y_ref - Yy);

                            InverseKinematics(3.2, -uX, -uY); 

                            //ESP_LOGI(TAG, "uX: %f, xref: %f, uunsat: %f, Xm: %f", uX, x_ref, u_unsatX, Xy);

                            idx = (idx + 1) % N_actual;

                    }


                        break;
                    }

                    //==================================== R E D   N E U R O N A L =========================================
                    case 3:{
                        //simular_tiempo_real(angle, L4, L5);
                        convertirTouch((float)measuredX, (float)measuredY, radioX, radioY, radioXmag, radioYmag, angleIn, Xmin, Xmax, Ymin, Ymax);
                        
                        vx = (float)measuredX - prevMeasuredX;
                        vy = (float)measuredY - prevMeasuredY;
                        
                        red_neuronal(0, angleIn, radioXmag, vx, radioX, Rvecx);

                        R4x = Rvecx[4];
                        R5x = Rvecx[5];
                        R6x = Rvecx[6];
                        R7x = Rvecx[7];

                        red_neuronal(1, angleIn, radioYmag, vy, radioY, Rvecy);

                        R4y = Rvecy[4];
                        R5y = Rvecy[5];

                        
                        Serial.print(R4x, 6);
                        Serial.print(",");
                        Serial.print(R5x, 6);
                        Serial.print(",");
                        Serial.print(R4y, 6);
                        Serial.print(",");
                        Serial.println(R5y, 6);




                        InverseKinematics(3.2, R5x-R4x, R5y-R4y);

                        prevMeasuredX = (float)measuredX;
                        prevMeasuredY = (float)measuredY;

                        //ESP_LOGI(TAG, "ang: %.1f | rmg: %.3f | rX: %.3f | vx: %.3f | R4=%.4f | R5=%.4f ", angleIn, radioXmag, radioX, vx, R4x, R5x);
                        //ESP_LOGI(TAG, "Vel: %.1f | R6x: %.3f | R7x: %.3f | R4: %.3f | R5: %.3f", vx, R6x*WdReact[0], R7x*WdReact[1], R4x, R5x);

                        



                        break;
                    }
                    default:
                        break;
                }
                break;
            }

            case CINEMATICAINVERSA: {
                
                //PULGADAS
                //Mínimo práctico: 2.34 
                //Máximo práctico: 4.11

                //Mínimo teórico: 1
                //Máximo teórico: 4

                //Max nx = 0.4
                //Max ny = 0.4
            
                // Si hay datos disponibles en el puerto serie
                if (Serial.available()) {
                    inputString = Serial.readStringUntil('\n');  // lee hasta salto de línea
                    inputString.trim();                          // quita espacios
                    
                    // divide por comas
                    int firstComma = inputString.indexOf(',');
                    int secondComma = inputString.indexOf(',', firstComma + 1);

                    if (firstComma > 0 && secondComma > 0) {
                        String nxStr = inputString.substring(0, firstComma);
                        String nyStr = inputString.substring(firstComma + 1, secondComma);
                        String hzStr = inputString.substring(secondComma + 1);

                        nx = nxStr.toDouble();
                        ny = nyStr.toDouble();
                        hz = hzStr.toDouble();

                        // guarda también en datosIK si quieres
                        datosIK.nx = nx;
                        datosIK.ny = ny;
                        datosIK.hz = hz;

                        Serial.printf("Recibido nx=%.3f ny=%.3f hz=%.3f\n", nx, ny, hz);
                    }
                }


                InverseKinematics(hz, nx, ny);

                break;
            }

            default:
                break;

        }

            

        vTaskDelay(xDelay);
            
    }
}


